mapper.select:
SELECT 
FROM evaluation_run run
JOIN practice_session session ON session.id = run.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE run.session_id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}

INSERT INTO evaluation_run (id, session_id, model_call_job_id, workflow_version)
SELECT #{id, jdbcType=OTHER},
       session.id,
       #{modelCallJobId, jdbcType=OTHER},
       #{workflowVersion, jdbcType=BIGINT}
FROM practice_session session
JOIN learning_task task ON task.id = session.task_id
JOIN model_call_job job ON job.id = #{modelCallJobId, jdbcType=OTHER}
WHERE session.id = #{sessionId, jdbcType=OTHER}
  AND session.status = 'COMPLETED'
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND job.user_id = #{trustedUserId, jdbcType=OTHER}
  AND job.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND job.model_purpose = #{modelPurpose, jdbcType=VARCHAR}
  AND job.model_operation = #{modelOperation, jdbcType=VARCHAR}
  AND job.workflow_id = #{id, jdbcType=OTHER}
  AND job.workflow_step_id = #{workflowStepId, jdbcType=VARCHAR}
  AND job.workflow_version = #{workflowVersion, jdbcType=BIGINT}
RETURNING id, session_id, model_call_job_id, status, workflow_version, row_version, created_at, completed_at
